// 当前候选的毛支出观察必须服从真实recipe与savepoint原子性，不从余额差补造消费。
#include "resident/storage/common_store.hpp"
#include <iostream>
#include <limits>
using namespace hanmo::resident;
namespace {
int checks=0;
// 独立断言在发行优化配置下也执行，首错阻止无效夹具继续掩盖错误。
void check(bool ok,const char* label){++checks;if(!ok)throw std::runtime_error(label);}
void good(const Status& result){if(!result.ok)throw std::runtime_error(result.error.original.code);}
// 只建两个真实共同钱包，测试不借用替代账本或动作收费公式。
CommonStore fixture(Integer balance=100){CommonState state;Owner player{Owner::Kind::actor,"player",{}},other{Owner::Kind::actor,"other",{}};state.wallets.insert("private",{"private",player,balance,{}});state.wallets.insert("other",{"other",other,100,{}});return CommonStore(std::move(state),std::make_shared<CommonCatalog>());}
// 同recipe收入即使大于支出，许可消耗仍是所有真实负向WalletDelta之和。
void gross_and_reservations(){auto store=fixture();good(store.begin_wallet_debit_observation("private"));good(store.apply_resources({{WalletDelta{"private",50},WalletDelta{"private",-30},WalletDelta{"private",-20},WalletDelta{"private",100},WalletDelta{"other",-40}},{}}));check(store.wallet("private")->balance==200&&store.wallet("other")->balance==60,"actual income and spending applied");check(store.observed_wallet_debits()==50,"incoming money and other wallet never offset selected gross spending");
    good(store.apply_resources({{SetReservation{"private","action:1",80,false}},{}}));check(store.spendable("private").value==120&&store.observed_wallet_debits()==50,"reserving money is not payment");good(store.apply_resources({{SetReservation{"private","action:1",10,false}},{}}));good(store.apply_resources({{ReleaseActionResources{"action:1"}},{}}));check(store.wallet("private")->reserved.empty()&&store.wallet("private")->balance==200&&store.observed_wallet_debits()==50,"reservation reduction and release are not refunds or spending");
    auto busy=store.begin_wallet_debit_observation("other");check(!busy.ok&&busy.error.original.code=="RunSpendObservationBusy"&&store.observed_wallet_debits()==50,"cannot replace selected wallet during observation");store.clear_wallet_debit_observation();good(store.apply_resources({{WalletDelta{"private",-7}},{}}));check(store.observed_wallet_debits()==0&&store.wallet("private")->balance==193,"clear removes observer from later manual command");good(store.begin_wallet_debit_observation("private"));check(store.observed_wallet_debits()==0,"new candidate observation starts at zero");}
// 失败recipe不发布已暂存的借记，NPC局部撤销同时恢复观察与资源版本。
void failed_recipe_and_savepoint(){auto store=fixture();good(store.begin_wallet_debit_observation("private"));good(store.apply_resources({{WalletDelta{"private",-3}},{}}));const auto before=store.wallet("private")->balance;const auto version=store.read_version({ResourceKey::Kind::wallet,"private"}).version;auto denied=store.apply_resources({{WalletDelta{"private",-10},WalletDelta{"missing",-1}},{}});check(!denied.ok&&denied.error.original.code=="UnknownWallet","late recipe failure occurs after staged debit");check(store.wallet("private")->balance==before&&store.observed_wallet_debits()==3&&store.read_version({ResourceKey::Kind::wallet,"private"}).version==version,"failed recipe leaks no balance debit or resource version");
    auto mark=store.begin_savepoint();check(mark.ok,"savepoint starts with observed prefix");good(store.apply_resources({{WalletDelta{"private",-9},WalletDelta{"private",5}},{}}));check(store.wallet("private")->balance==93&&store.observed_wallet_debits()==12,"savepoint sees gross intermediate debit");good(store.rollback_savepoint(mark.value));check(store.wallet("private")->balance==97&&store.observed_wallet_debits()==3&&store.read_version({ResourceKey::Kind::wallet,"private"}).version==version,"rollback restores exact observed prefix and resource version");
    mark=store.begin_savepoint();check(mark.ok,"committing savepoint starts");good(store.apply_resources({{WalletDelta{"private",-4}},{}}));good(store.commit_savepoint(mark.value));check(store.wallet("private")->balance==93&&store.observed_wallet_debits()==7,"committed savepoint retains real spending");
    store.clear_wallet_debit_observation();mark=store.begin_savepoint();check(mark.ok,"observer-free savepoint starts");auto rejected=store.begin_wallet_debit_observation("private");check(!rejected.ok&&rejected.error.original.code=="RunSpendObservationBusy","cannot install observer inside an unrelated savepoint");good(store.rollback_savepoint(mark.value));auto unknown=store.begin_wallet_debit_observation("missing");check(!unknown.ok&&unknown.error.original.code=="UnknownWallet"&&store.observed_wallet_debits()==0,"unknown wallet never creates observation");}
// 复制共同权威只复制资产，短寿命许可观察不得进入下一个候选。
void copy_isolation(){auto store=fixture();good(store.begin_wallet_debit_observation("private"));good(store.apply_resources({{WalletDelta{"private",-8}},{}}));auto copied=store;check(copied.wallet("private")->balance==92&&copied.observed_wallet_debits()==0,"copy constructor discards observer");good(copied.apply_resources({{WalletDelta{"private",-5}},{}}));check(copied.observed_wallet_debits()==0&&store.observed_wallet_debits()==8&&store.wallet("private")->balance==92,"unobserved clone cannot affect source observer");good(copied.begin_wallet_debit_observation("other"));good(copied.apply_resources({{WalletDelta{"other",-6}},{}}));check(copied.observed_wallet_debits()==6&&store.observed_wallet_debits()==8,"clone can choose independent observation");copied=store;check(copied.observed_wallet_debits()==0&&copied.wallet("private")->balance==92,"copy assignment clears destination observer");good(copied.begin_wallet_debit_observation("private"));check(copied.observed_wallet_debits()==0,"assigned candidate admits new observer");}
// 极端负数与累计毛支出溢出先拒绝整个recipe，不产生有符号溢出或部分借记。
void arithmetic_refusal(){const auto maximum=std::numeric_limits<Integer>::max();const auto minimum=std::numeric_limits<Integer>::min();auto store=fixture(maximum);good(store.begin_wallet_debit_observation("private"));auto denied=store.apply_resources({{WalletDelta{"private",minimum,false}},{}});check(!denied.ok&&denied.error.original.code=="RunMoneyOverflow"&&store.wallet("private")->balance==maximum&&store.observed_wallet_debits()==0,"INT64_MIN cannot be negated into observed debit");
    denied=store.apply_resources({{WalletDelta{"private",-maximum},WalletDelta{"private",maximum},WalletDelta{"private",-1}},{}});check(!denied.ok&&denied.error.original.code=="RunMoneyOverflow"&&store.wallet("private")->balance==maximum&&store.observed_wallet_debits()==0,"same-recipe gross overflow rejects all staged operations");good(store.apply_resources({{WalletDelta{"private",-maximum}},{}}));good(store.apply_resources({{WalletDelta{"private",maximum}},{}}));check(store.wallet("private")->balance==maximum&&store.observed_wallet_debits()==maximum,"largest representable gross amount survives incoming refund");const auto version=store.read_version({ResourceKey::Kind::wallet,"private"}).version;denied=store.apply_resources({{WalletDelta{"private",-1}},{}});check(!denied.ok&&denied.error.original.code=="RunMoneyOverflow"&&store.wallet("private")->balance==maximum&&store.observed_wallet_debits()==maximum&&store.read_version({ResourceKey::Kind::wallet,"private"}).version==version,"cross-recipe observation overflow refuses adoption");
    auto short_wallet=fixture(1);good(short_wallet.begin_wallet_debit_observation("private"));denied=short_wallet.apply_resources({{WalletDelta{"private",-2}},{}});check(!denied.ok&&denied.error.original.code=="InsufficientFunds"&&short_wallet.wallet("private")->balance==1&&short_wallet.observed_wallet_debits()==0,"ordinary resource shortage remains authoritative");}
}
// 本门只运行变更相关资金primitive，不导入世界或重跑原领域矩阵。
int main(){try{gross_and_reservations();failed_recipe_and_savepoint();copy_isolation();arithmetic_refusal();std::cout<<"WALLET_DEBIT_OBSERVATION "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& error){std::cerr<<"WALLET_DEBIT_OBSERVATION_FAILURE "<<error.what()<<" after "<<checks<<" checks\n";return 1;}}
